  "auth.aboutLink": "Luminous StockHaven সম্পর্কে",
  'about.bookshopLeadIn': "আমাদের বইয়ের দোকান চালানো একই ছোট ব্যবসার তৈরি:",
  "about.eyebrow": "Luminous StockHaven সম্পর্কে",
  "about.pageTitle": "Luminous StockHaven — আমাদের সম্পর্কে",
  "about.founderHeading": "📖 প্রতিষ্ঠাতা সম্পর্কে",
  "about.founder.p1": "হ্যালো, আমি কনসেপসিওন, Luminous StockHaven-এর প্রতিষ্ঠাতা।",
  "about.founder.p2": "আমি কোনো বড় প্রযুক্তি কোম্পানি থেকে আসিনি, আর আমি কোনো কর্পোরেট অফিসে বসি না। আমি একজন ছোট খুচরা বিক্রেতা, ঠিক আপনার মতো। আমি পাঁচটি ই-কমার্স দোকান পরিচালনা করি, যেগুলো বই এবং বইপ্রেমীদের জন্য হাতে তৈরি জিনিসপত্রে বিশেষজ্ঞ।\nঅনেক স্বাধীন খুচরা বিক্রেতার মতো, আমি একটা ভাঙনের মুখে পৌঁছেছিলাম যখন একাধিক স্থানের মজুদ সামলানো, প্রকাশকদের ISBN আমার নিজের হাতে তৈরি SKU-এর পাশাপাশি অনুসরণ করা, এবং অসুবিধাজনক স্প্রেডশিট দিয়ে সরবরাহকারীদের অর্ডার সামলানো কঠিন হয়ে পড়েছিল। যখন আমি সাহায্যের জন্য একটি অ্যাপ খুঁজলাম, আমি ছয়টি ভিন্ন বিকল্প চেষ্টা করলাম। প্রতিটিই ছিল হয় সম্পূর্ণ অসম্পূর্ণ, অবিশ্বাস্যভাবে বিভ্রান্তিকর, অথবা শিকারি — মৌলিক সরঞ্জামের জন্য মাসে শত শত ডলার নিত।",
  "about.founder.p3": "স্বাধীন স্রষ্টাদের শোষণ করা একটি শিল্পে হতাশ হয়ে, আমি নিজের সমাধান নিজে তৈরি করার সিদ্ধান্ত নিলাম। আমি Luminous StockHaven তৈরি করেছি প্রয়োজন থেকে, যাতে আমি আমার নিজের ব্যবসাগুলো পরিষ্কারভাবে, দক্ষতার সাথে এবং সম্পূর্ণ মানসিক শান্তিতে চালাতে পারি।",
  "about.founder.p4": "আমি এই প্ল্যাটফর্মটি সৎ ও সাশ্রয়ী দামে জনসাধারণের জন্য খুলে দেওয়ার সিদ্ধান্ত নিয়েছি, কারণ প্রতিটি ছোট ব্যবসায়ী এমন সরঞ্জামের যোগ্য যা সত্যিই কাজ করে, তার আয়কে ঝুঁকিতে না ফেলে। আমরা স্বাধীনভাবে মালিকানাধীন, আমাদের সম্প্রদায়কে প্রবলভাবে রক্ষা করি, এবং একজন খুচরা বিক্রেতার দ্বারা, খুচরা বিক্রেতাদের জন্য তৈরি।",
  "notice.ariaLabel": "ট্রেডমার্ক ও কপিরাইট বিজ্ঞপ্তি",
  "notice.heading": "🛡️ খুচরা বিক্রেতাদের জন্য তৈরি, কর্পোরেট শকুনদের কাছে অমূল্য",
  "notice.intro": "আমি এই অ্যাপটি তৈরি করেছি কারণ আমি ৫টি দোকান চালাই এবং শত শত ডলারের বিভ্রান্তিকর সফটওয়্যারে ঠকতে ঠকতে ক্লান্ত হয়ে পড়েছিলাম। এই অ্যাপটি তৈরি করা হয়েছে স্বাধীন শিল্পী, কারিগর, বই বিক্রেতা এবং স্থানীয় দোকানগুলোকে রক্ষা করার জন্য।",
  "notice.legalHeading": "প্রতিযোগী ও অনুকরণকারীদের জন্য আইনি বিজ্ঞপ্তি:",
  "notice.legalBody": "আমরা সক্রিয়ভাবে বাজার পর্যবেক্ষণ করি। আমাদের প্ল্যাটফর্ম থেকে তথ্য সংগ্রহ, আমাদের মালিকানাধীন কর্মপ্রবাহের নকল, বা আমাদের মেধাস্বত্ব লঙ্ঘনের যেকোনো চেষ্টা তাৎক্ষণিক ও আক্রমণাত্মক আইনি পদক্ষেপের মুখোমুখি হবে।",
  "notice.acquisitionHeading": "অধিগ্রহণ সংস্থা ও দালালদের উদ্দেশে:",
  "notice.acquisitionBody": "আমাকে ইমেল করবেন না। আমাকে বার্তা পাঠাবেন না। আমাকে 'কৌশলগত প্রস্থান'-এর প্রস্তাব দেবেন না। আপনারা হাজার, লক্ষ, কোটি বা ট্রিলিয়ন প্রস্তাব করতে পারেন — উত্তর হলো না। আপনারা এই অ্যাপটি কিনবেন না শুধু আমার সহকর্মী ব্যবসায়ীদের জন্য দাম বাড়ানোর জন্য। প্রতিটি অযাচিত অধিগ্রহণ ইমেল তাৎক্ষণিকভাবে স্প্যাম হিসেবে চিহ্নিত হবে, এবং আপনাদের ডোমেইন আমাদের প্ল্যাটফর্ম থেকে স্থায়ীভাবে অবরুদ্ধ করা হবে। পরিশ্রম বাঁচান।",
  "footer.trademarkLine": "অননুমোদিত অনুলিপি, ক্লোনিং বা তথ্য সংগ্রহ কঠোরভাবে নিষিদ্ধ।",
