  "thankYou.unverified.trialNotEligible": "এই ইমেইল ইতিমধ্যে তার একমাত্র বিনামূল্যের ট্রায়াল ব্যবহার করেছে, তাই ট্রায়াল শুরু করা যায়নি। ভুল মনে হলে সহায়তার সঙ্গে যোগাযোগ করুন।",
