  "settings.details.taxModeAutomatic": "স্বয়ংক্রিয় — গ্রাহকের রাজ্য অনুযায়ী",
  "settings.details.taxModeHint": "নির্দিষ্ট মোড প্রতিটি নতুন অর্ডারে আপনার হার ব্যবহার করে। স্বয়ংক্রিয় মোড, রাজ্য অর্ডারে থাকলেই, নতুন অর্ডারের কর গ্রাহকের রাজ্যের ভিত্তি হার দিয়ে পূরণ করে, এবং রাজ্য বদলালে আবার পূরণ করে। এগুলো রাজ্যের ভিত্তি হার — স্থানীয় কর আরও যোগ হতে পারে। যে অর্ডারে কোনো রাজ্য নেই, বা যা যুক্তরাষ্ট্রের বাইরের, তা উপরে দেওয়া আপনার নির্দিষ্ট হার ব্যবহার করে।",
  'settings.details.gs1Prefix': "GS1 কোম্পানি প্রিফিক্স",
  'settings.details.gs1PrefixHint': "শুধুমাত্র যদি আপনার GS1 থেকে প্রিফিক্সের লাইসেন্স থাকে। একবার সেট করুন এবং পণ্যের ফর্মের কোড জেনারেটর আপনার নিজের নম্বর থেকে আসল খুচরা UPC ও EAN কোড তৈরি করতে পারবে — প্রতিটি শুধু একবার ব্যবহৃত হবে এবং কখনও পুনরায় নয়। না থাকলে ফাঁকা রাখুন; অ্যাপ কখনও প্রিফিক্স বানায় না।",
