  "settings.pastDue.body": "আপনার শেষ পেমেন্ট সম্পন্ন হয়নি। ব্যর্থ পেমেন্ট থেকে 14 দিন পর্যন্ত আপনি পূর্ণ ব্যবহার পাবেন, যতক্ষণ না আপনি এটি ঠিক করেন। যদি ঠিক না হয়, সাবস্ক্রিপশন বাতিল হয়ে যাবে, ওয়ার্কস্পেস 15 দিনের জন্য শুধু দেখার মতো থাকবে, এবং তারপর অ্যাকাউন্ট ও তার সমস্ত তথ্য মুছে ফেলা হবে। মুছে ফেলার আগে যেকোনো সময় পেমেন্ট করলে সবকিছু ফিরে আসে। আপনি যদি নিশ্চিত না হন কী করতে হবে, theluminousbookshop@outlook.com-এ সহায়তার সাথে যোগাযোগ করুন।",
