  "settings.software.fixedNote": "এই মানগুলো স্থির এবং প্রতিটি ব্যবসার ক্ষেত্রে একইভাবে দেখা যায়। ব্যবসার নাম বদলানো বা লোগো পরিবর্তন করলে অ্যাপ্লিকেশনের নাম কখনো বদলায় না।",
