  "training.newForYou": "আপনার জন্য নতুন প্রশিক্ষণ",
  "training.newForYouHelp": "এই পাঠগুলো যোগ করা হয়েছে কারণ আপনার ভূমিকা বেড়েছে, অথবা কেউ আপনাকে এগুলো বরাদ্দ করেছে। অ্যাপের নতুন অংশগুলো শিখতে এগুলো শেষ করুন।",
