  "settings.security.codesOnceWarning": "এই কোডগুলো কেবল একবারই দেখানো হয় — আমরা কেবল একটি এলোমেলো অনুলিপি রাখি, তাই আমরাও সেগুলো আবার দেখাতে পারি না। একটি নতুন সেট তৈরি করলে প্রতিটি পুরোনো কোড বাতিল হয়।",
  "settings.security.printCodes": "এই কোডগুলো মুদ্রণ করুন",
  "settings.security.backupEmailTitle": "ব্যাকআপ ইমেইল",
  "settings.security.backupEmailDesc": "আপনি নিয়ন্ত্রণ করেন এমন একটি দ্বিতীয় ইমেইল ঠিকানা। আপনার প্রধান ইমেইল কখনো নাগালের বাইরে হলে, এর বদলে এখানে একটি পুনরুদ্ধার কোড পাঠানো যায়।",
  "settings.security.backupEmailLabel": "ব্যাকআপ ইমেইল ঠিকানা",
  "settings.security.backupEmailSave": "যাচাইকরণ কোড পাঠান",
