  "settings.security.changeEmailTitle": "আপনার অ্যাকাউন্ট ইমেইল বদলান",
  "settings.security.changeEmailDesc": "আপনার অ্যাকাউন্ট একটি নতুন ইমেইলে সরান। আপনার দোকান, ইনভেন্টরি, দল ও ইতিহাস এর সঙ্গে সরে — এবং কোনো নতুন বিনামূল্যের ট্রায়াল শুরু হয় না। অন্য প্রতিটি সাইন-ইন করা ডিভাইস সাইন আউট হয়।",
