  "crossStore.transferToLocation": "কোন স্থানে",
  "training.lessons.owner-move-stock.step1": "অনুরোধ হলো চাওয়ার জন্য; সরানো মালিকদের কাজ। ক্রস-স্টোর ইনবক্স পৃষ্ঠায় স্টক সরান প্যানেল আপনাকে — মালিককে — কোনো অনুরোধ ও অপেক্ষা ছাড়াই এই দোকান থেকে আপনার অন্য দোকানে সরাসরি স্টক পাঠাতে দেয়।",
  "training.lessons.owner-move-stock.step2": "পণ্য, সেটি যেখান থেকে যাবে সেই স্থান এবং পরিমাণ বেছে নিন। অ্যাপটি দেখায় সেই স্থানে কতটি হাতে আছে, এবং কোনো সরানো কখনো তার বেশি নিতে পারে না।",
  "training.lessons.owner-move-stock.step3": "গন্তব্য দোকান বেছে নিন, এবং চাইলে সেখানকার নির্দিষ্ট স্থানটিও। সেই দোকানে ইতিমধ্যে একই SKU থাকলে স্টক সেই পণ্যের সঙ্গে যুক্ত হয়; না থাকলে পণ্যটি স্টকসহ কপি হয়ে যায়।",
  "training.lessons.owner-move-stock.step4": "দুটি দোকানই রেকর্ড রাখে: এই দোকান একটি বহির্গামী স্থানান্তর দেখায়, অন্যটি একটি প্রাপ্তি দেখায়। সরানো সম্ভব না হলে — হাতে যথেষ্ট না থাকলে, কিংবা অন্য দোকানটি আপনার না হলে — কিছুই সরে না এবং অ্যাপটি কারণটি বলে দেয়।",
  "training.lessons.owner-move-stock.title": "নিজের দোকানগুলোর মধ্যে স্টক সরানো (Business প্ল্যান)",
