  "pricing.businessOnly": "ক্লিয়ারেন্স ও রোলব্যাক মূল্য Business প্ল্যানের অংশ।",
  "pricing.clearanceBadge": "ক্লিয়ারেন্স",
  "pricing.clearanceHint": "একটি স্থায়ী মূল্য হ্রাস। আপনি এটিকে স্বাভাবিক মূল্যে ফিরিয়ে না আনা পর্যন্ত এটি থাকে।",
  "pricing.clearancePriceLabel": "ক্লিয়ারেন্স মূল্য",
  "pricing.endLabel": "শেষ",
  "pricing.modeClearance": "ক্লিয়ারেন্স",
  "pricing.modeLabel": "মূল্য নির্ধারণ",
  "pricing.modeRegular": "স্বাভাবিক মূল্য",
  "pricing.modeRollback": "রোলব্যাক (অস্থায়ী সেল)",
  "pricing.rollbackBadge": "রোলব্যাক",
  "pricing.rollbackHint": "সেল চলাকালীন স্বাভাবিক মূল্যটি রাখা হয় এবং রোলব্যাক মূল্যের পাশে দেখানো হয়। শেষের তারিখ পেরিয়ে গেলে মূল্য নিজে নিজেই স্বাভাবিকে ফিরে আসে।",
  "pricing.rollbackStarts": "রোলব্যাক শুরু হবে {date}",
  "pricing.salePriceLabel": "রোলব্যাক মূল্য",
  "pricing.sectionTitle": "বিক্রয় মূল্য",
  "pricing.startLabel": "শুরু",
  "training.lessons.mgr-pricing.step1": "Business-এ পণ্যের ফর্মে একটি বিক্রয় মূল্য বিভাগ থাকে। ক্লিয়ারেন্স একটি স্থায়ী মূল্য হ্রাস — নির্ধারণ করুন এবং এটি থেকে যায়। রোলব্যাক তারিখসহ একটি সেল: রোলব্যাক মূল্য, শুরুর দিন এবং শেষের দিন নির্ধারণ করুন।",
  "training.lessons.mgr-pricing.step2": "আপনাকে কখনো স্বাভাবিক মূল্য আবার লিখতে হয় না: এটি পণ্যে থাকে এবং পণ্য তালিকা ও স্ক্যানারে বিক্রয় মূল্যের পাশে দেখা যায়, যাতে যে কেউ দেখতে পারে পণ্যটির স্বাভাবিক মূল্য কত।",
  "training.lessons.mgr-pricing.step3": "রোলব্যাক শুরু হলে নতুন মূল্য লেবেল ছাপান — লেবেলগুলো সেই মূল্য ছাপে যা গ্রাহক সেদিন দেন। শেষের তারিখ পেরিয়ে গেলে মূল্য নিজেই স্বাভাবিকে ফিরে আসে; তাক তাজা করার সময় স্বাভাবিক লেবেল আবার ছাপান।",
  "training.lessons.mgr-pricing.step4": "বিক্রয় মূল্য বিভাগটি বন্ধ দেখালে, ব্যবসাটি Business প্ল্যানে নেই — বিক্রয় মূল্য সেই প্ল্যানের অন্তর্গত, এবং প্ল্যান পরিবর্তন করেন মালিক।",
  "training.lessons.mgr-pricing.title": "সেল চালানো: ক্লিয়ারেন্স ও রোলব্যাক",
  "training.lessons.owner-pricing.step1": "পণ্যের ফর্মে, বিক্রয় মূল্যের অধীনে, দুই ধরনের মূল্য হ্রাস থাকে। ক্লিয়ারেন্স স্থায়ী: ক্লিয়ারেন্স মূল্য নির্ধারণ করুন এবং আপনি ফিরিয়ে না আনা পর্যন্ত এটি কম থাকে। রোলব্যাক একটি অস্থায়ী সেল — শুরু ও শেষের তারিখসহ একটি কম মূল্য, বড় দোকানগুলো থেকে আপনি যে সেল ইতিমধ্যে জানেন তার মতো।",
  "training.lessons.owner-pricing.step2": "স্বাভাবিক মূল্য কখনো মোছা হয় না। রোলব্যাক চলাকালীন অ্যাপটি বিক্রয় মূল্যের পাশে স্বাভাবিক মূল্য দেখায়, এবং ছাপা লেবেলগুলো বিক্রয় মূল্য বহন করে, যাতে তাক আর ক্যাশ মিলে যায়।",
  "training.lessons.owner-pricing.step3": "শেষের তারিখ পেরিয়ে গেলে মূল্য নিজেই স্বাভাবিকে ফিরে আসে — মনে রাখার কিছু নেই, পূর্বাবস্থায় ফেরানোর কিছু নেই। যে রোলব্যাক এখনো শুরু হয়নি, তা পণ্য তালিকাতেই তার শুরুর তারিখ বলে দেয়।",
  "training.lessons.owner-pricing.step4": "বিক্রয় মূল্য Business প্ল্যানের একটি বৈশিষ্ট্য। Essentials-এ ক্ষেত্রগুলো বন্ধ থাকে, এবং কোনো ব্যবসা Essentials-এ নেমে আবার ফিরে এলে, তার ক্লিয়ারেন্স ও রোলব্যাক সেটিং ঠিক যেভাবে রেখে যাওয়া হয়েছিল সেভাবেই থাকে।",
  "training.lessons.owner-pricing.title": "ক্লিয়ারেন্স ও রোলব্যাক মূল্য (Business প্ল্যান)",
  "plansLib.includes.shippingLabels": "গ্রাহকের অর্ডারের জন্য 4×6 শিপিং লেবেল — অথবা আপনার বাহকের লেবেল ফাইলে রাখুন",
