  "print.carrier.title": "আপনার বাহকের লেবেল",
  "print.carrier.desc": "আজকের মতোই বাহকের কাছ থেকে ডাক খরচ কিনুন — এই অ্যাপ কখনো ডাক খরচ বিক্রি করে না, তাই আপনি যে দাম দেন তা সবসময় বাহকের নিজের দাম। লেবেলের ফাইলটি এখানে সংরক্ষণ করুন এবং এটি এই অর্ডারে চিরদিন থাকবে: আপনার রেকর্ড, কিছু ঘটলে হাতের কাছে।",
