  "print.style.title": "নথির ধরন",
  "print.style.desc": "আপনার নথিগুলোকে আপনার নিজের করুন। এই পছন্দগুলো আপনার চালান, রসিদ, প্যাকিং স্লিপ, ফেরতের নথি, পণ্যের শিট, গণনা শিট এবং বাছাই তালিকাকে সাজায় — এবং আপনার ব্যবসার জন্য মনে রাখা হয়।",
