  "print.style.imageSizeHint": "প্রস্থ হলো পৃষ্ঠার প্রস্থের যতটা অংশ ছবিটি জুড়ে থাকে; দৈর্ঘ্য হলো ছাপার সর্বোচ্চ উচ্চতা। স্বাভাবিক আকারের জন্য বাক্সটি খালি রাখুন।",
  "print.printedAt": "{date} তারিখে {time} টায় মুদ্রিত",
  "print.style.previewText": "দ্রুত বাদামি শিয়াল অলস কুকুরের উপর দিয়ে লাফ দেয়। 1234567890",
  "training.lessons.owner-shipping-labels.step1": "প্রিন্ট সেন্টারে দুটি প্ল্যানেই শিপিং লেবেল স্টাইল আছে: গ্রাহকের অর্ডার বেছে নিন এবং ক্রেতার নাম ও ঠিকানা এবং প্রেরক হিসেবে আপনার ব্যবসাসহ একটি 4×6 লেবেল ছাপুন।",
  "training.lessons.owner-shipping-labels.step2": "লেবেলটি প্রতিটি গ্রাহক নথির মতোই হোয়াইট-লেবেল: এতে শুধু আপনার ব্যবসার নাম থাকে — এই অ্যাপের নাম কখনই নয় — যাতে আপনার দোকান থেকে আসা পার্সেল আপনার দোকান থেকেই এসেছে বলে মনে হয়।",
  "training.lessons.owner-shipping-labels.step3": "গ্রাহকের ঠিকানা তাদের শেষ অর্ডারের পর 90 দিন পর্যন্ত তাদের অর্ডারের সাথে রাখা হয়, এবং লেবেলটি যখন অর্ডারের সংরক্ষিত ঠিকানা থাকে তখন তা থেকে শুরু হয়; একবারের লেবেলের জন্য প্রিন্টের সময় টাইপ করা ঠিকানা ফেরত সংরক্ষণ করা হয় না। নামটি তবুও অর্ডার থেকে পূরণ হয় যাতে লেবেল কাগজপত্রের সাথে মিলে।",
  "training.lessons.owner-shipping-labels.step4": "লেবেলটি প্রতিটি লেবেলের মতো একই চারটি সংযোগে ছাপা হয় — ব্লুটুথ, ওয়াই-ফাই, ইথারনেট ও USB — এবং 4×6 থার্মাল প্রিন্টারই এর মান মাপ।",
  "training.lessons.owner-shipping-labels.step5": "বরং বাহকের কাছ থেকে ডাক খরচ কিনেছেন? এই একই বিভাগে আপনি বাহকের লেবেল ফাইল — PDF, PNG বা JPG — আপলোড করতে পারেন এবং এটি অর্ডারে চিরদিন সংরক্ষিত থাকে: আপনার রেকর্ড, কিছু ঘটলে হাতের কাছে। এটি তার আসল 4×6 আকারে ছাপা হয়। অ্যাপ কখনো ডাক খরচ বিক্রি করে না, তাই বাহকের দামই একমাত্র দাম — এবং সবসময় সঠিক দাম।",
  "training.lessons.owner-shipping-labels.title": "গ্রাহকের অর্ডারের জন্য শিপিং লেবেল",
  "training.lessons.print-shipping-label.step1": "যখন কোনো অর্ডার পাঠানোর জন্য প্রস্তুত, প্রিন্ট সেন্টার খুলুন, শিপিং লেবেল স্টাইল বেছে নিন এবং তারপর গ্রাহকের অর্ডার বেছে নিন। ক্রেতার নাম অর্ডার থেকে পূরণ হয়ে যায়।",
  "training.lessons.print-shipping-label.step2": "পার্সেলটি যে ঠিকানায় যাচ্ছে তা যাচাই করুন। যখন অর্ডারে গ্রাহকের ঠিকানা থাকে — তাদের শেষ অর্ডারের পর 90 দিন পর্যন্ত রাখা — তখন এটি আপনার জন্য পূরণ হয়ে যায়; প্রিন্টের সময় আপনি যে ঠিকানা টাইপ করেন তা ফেরত সংরক্ষণ করা হয় না, তাই প্রিন্ট করার আগে পোস্টকোড এবং শেষ লাইনটি সাবধানে যাচাই করুন।",
  "training.lessons.print-shipping-label.step3": "আপনার ব্যবসার নাম প্রেরক হিসেবে উপরে ছাপা হয়। লেবেলে আপনার ঠিকানাও চাইলে প্রেরকের ঠিকানার বাক্সে লিখুন; দেখাতে না চাইলে খালি রাখুন।",
  "training.lessons.print-shipping-label.step4": "4×6 লেবেলে ছাপুন — থার্মাল লেবেল প্রিন্টারই সাধারণত মানানসই — অথবা ব্রাউজারের প্রিন্ট বোতাম দিয়ে যেকোনো প্রিন্টারে। লেবেলটি পার্সেলের উপর সমতলভাবে লাগান, যেখানে তা কোনো ধারে ভাঁজ হবে না।",
  "training.lessons.print-shipping-label.step5": "ডাক খরচ বাহকের কাছ থেকে কেনা হলে, তার বদলে তাদের লেবেল ফাইলটি অর্ডারে সংরক্ষণ করুন: আপনার বাহকের লেবেল বিভাগে বাহক আপনাকে দেওয়া PDF, PNG বা JPG আপলোড করুন। এটি আপনার রেকর্ড হিসেবে অর্ডারে থাকে এবং তার আসল 4×6 আকারে ছাপা হয় — এবং আপনি যখন ব্যবহার করতে চান, অ্যাপের নিজের ঠিকানার লেবেল সবসময় সেখানে থাকে।",
  "training.lessons.print-shipping-label.title": "একটি শিপিং লেবেল ছাপুন",
