  "workforce.messages.voiceNote": "ভয়েস নোট",
  "workforce.messages.recording": "রেকর্ড হচ্ছে…",
  "workforce.messages.stopRecording": "থামান",
  "workforce.messages.voiceReady": "আপনার ভয়েস নোট তৈরি। শুনুন, তারপর পাঠান — অথবা মুছে আবার রেকর্ড করুন।",
  "workforce.messages.sendVoice": "ভয়েস নোট পাঠান",
  "workforce.messages.discard": "মুছে ফেলুন",
  "workforce.messages.micDenied": "মাইক্রোফোন বন্ধ আছে, তাই ভয়েস নোট রেকর্ড করা যাচ্ছে না। আপনি আপনার ব্রাউজারের সেটিংসে মাইক্রোফোনের অনুমতি দিতে পারেন — অথবা এর বদলে শুধু একটি লিখিত বার্তা পাঠান।",
  "workforce.messages.voiceFailed": "ওই ভয়েস নোটটি পাঠানো যায়নি। অনুগ্রহ করে আবার চেষ্টা করুন।",
  "workforce.messages.sentLabel": "পাঠানো হয়েছে",
  "workforce.messages.receivedLabel": "পাওয়া গেছে",
  "workforce.messages.readLabel": "পড়া হয়েছে",
  "apiErrors.notFound.voiceNoteFound": "ভয়েস নোট পাওয়া যায়নি।",
  "apiErrors.invalidValue.sendVoiceRecording": "সর্বোচ্চ কয়েক মিনিটের ভয়েস রেকর্ডিং পাঠান।",
  "apiErrors.invalidValue.recordingNotPrepared": "ওই রেকর্ডিংটি তৈরি করা যায়নি — অনুগ্রহ করে আবার রেকর্ড করুন।",
  "training.lessons.messages-private.step5": "আপনি ভয়েস নোটও পাঠাতে পারেন: বার্তা বাক্সের পাশের মাইক্রোফোনে ছোঁয়ান, কথা বলুন, এবং থামান ছোঁয়ান। প্রথমে শুনুন — তারপর পাঠান, অথবা মুছে আবার রেকর্ড করুন। কেউ আপনাকে পাঠালে, তাদের আসল কণ্ঠ শুনতে চালান ছোঁয়ান।",
  "training.lessons.owner-messages-oversight.step5": "পড়ার চিহ্ন: দলের কোনো সদস্য আপনার পাঠানো বার্তা পড়লে, আপনি তা পড়া হয়েছে বলে চিহ্নিত দেখতে পান। কর্মী ও ব্যবস্থাপকেরা একে অপরের পড়ার চিহ্ন একইভাবে দেখেন, দুই দিকেই।",
  "training.lessons.owner-messages-oversight.step6": "আপনার নিজের পড়া অদৃশ্য। কোনো কর্মীর পাঠানো বার্তা আপনি পড়লে, তিনি কখনো পড়ার চিহ্ন দেখতে পান না — এবং আপনার দলকে বলার দরকার নেই যে তাদের কথোপকথন অ্যাপে সংরক্ষিত থাকে এবং আপনি, মালিক, সেগুলো পড়তে পারেন। এই তদারকি আপনার দোকানের যত্ন নেওয়ার অংশ।",
  "training.lessons.owner-messages-oversight.step7": "কর্মীদের মধ্যে নেতিবাচক বার্তা নিয়ে আপনি কী করবেন, তা আপনার ব্যাপার। এড়িয়ে যান, কারো সঙ্গে নীরবে কথা বলুন, অথবা ব্যবস্থা নিন — সিদ্ধান্ত আপনার, এবং আপনি কোথায় দেখেছেন তা কখনো বলতে হবে না।",
  "staffLib.perm.returnsComplete": "রিফান্ড ও বিনিময় সম্পূর্ণ করা",
  "staffLib.area.returnsAccess": "রিটার্নের অনুমোদন",
  "staff.memberDialog.returnsAccessHint": "এই টিক থাকলে এই ব্যক্তি একটি রিটার্ন অনুমোদন করতে এবং রিফান্ড বা বিনিময় সম্পূর্ণ করতে পারেন। এটি ছাড়া, তার শুরু করা রিটার্ন মালিক বা অনুমোদিত দলের সদস্যের অপেক্ষায় থাকে।",
  "returns.waitingApproval": "মালিক বা অনুমোদিত দলের সদস্যের অনুমোদনের অপেক্ষায়।",
  "returns.waitingToFinish": "অনুমোদিত — মালিক বা অনুমোদিত দলের সদস্য এই রিটার্নটি সম্পূর্ণ করবেন।",
  "apiErrors.returnsCompleteReserved": "শুধুমাত্র মালিক, অথবা সেই দলের সদস্য যাকে মালিক রিফান্ড ও বিনিময় সম্পূর্ণ করার অনুমতি দিয়েছেন, একটি রিটার্ন অনুমোদন করে সম্পূর্ণ করতে পারেন।",
  "staffLib.perm.productsCreate": "নতুন পণ্য যোগ করুন",
