  "staff.memberDialog.productsAccessHint": "এই টিক দিয়ে, এই ব্যক্তি «নতুন পণ্য» বোতামগুলি দেখেন এবং ক্যাটালগে পণ্য যোগ করতে পারেন। এটি ছাড়া, বোতামগুলি তাঁর কাছে দেখা যায় না।",
  "productForm.readIsbnTitle": "ছাপানো ISBN পড়ুন",
  "productForm.readIsbnHint": "ক্যামেরা বইয়ে ছাপানো ISBN-এর দিকে ধরুন এবং তারপর «নম্বর পড়ুন» চাপুন। বারকোড পড়া গেলে সেটিও নম্বরটি পূরণ করে দেয়।",
  "productForm.readIsbnButton": "নম্বর পড়ুন",
  "productForm.readIsbnWorking": "নম্বর পড়া হচ্ছে…",
