  "settings.policies.title": "আপনার দোকানের নীতি ও শর্তাবলি",
  "settings.policies.ownerDescription": "আপনার দোকান, আপনার নিয়ম। আপনার দোকানের নীতি এবং আপনার শর্তাবলি এখানে লিখুন — লিখে দিন, অথবা একটি ফাইল আপলোড করুন। দলের প্রতিটি নতুন সদস্য শুরু করার সময় এগুলো একবার দেখে, এবং আপনার পুরো দল যেকোনো সময় এখানে এগুলো পড়তে পারে। শুধু আপনিই এগুলো বদলাতে পারেন।",
  "settings.policies.memberDescription": "আপনার দোকানের নিজস্ব নীতি ও শর্তাবলি, মালিকের লেখা। শুধু মালিকই এগুলো বদলাতে পারেন।",
