  "apiErrors.trainingRecordTeam": "দলের রেকর্ড মালিক এবং ব্যবস্থাপকদের জন্য।",
  "profile.title": "আপনার প্রোফাইল ছবি",
  "profile.ownerDesc": "আপনার ছবি এবং যে নামে আপনার দল আপনাকে চেনে। আপনার নিজের ছবি সঙ্গে সঙ্গে দেখা যায় — কোনো অনুমোদনের প্রয়োজন নেই।",
  "profile.memberDesc": "মালিক অনুমোদন করলেই আপনার ছবি আপনার নামের পাশে দেখা যায়। ততক্ষণ পর্যন্ত শুধু আপনার নামের আদ্যক্ষর দেখা যায়।",
