  "profile.statePending": "আপনার ছবি মালিকের অনুমোদনের অপেক্ষায় আছে। তিনি অনুমোদন না করা পর্যন্ত এটি কোথাও দেখা যাবে না।",
  "profile.stateChangePending": "আপনার নতুন ছবি মালিকের অনুমোদনের অপেক্ষায় আছে। ততক্ষণ পর্যন্ত আপনার বর্তমান ছবিটি থাকবে।",
  "profile.choose": "একটি ছবি বেছে নিন",
