  "profile.declinedChange": "আপনার ছবি অনুমোদিত হয়নি — তবে আপনার অন্য ছবিটি এখনো আছে। আপনি যদি এটি পরিবর্তন করতে চান, অন্য একটি ছবি চেষ্টা করুন।",
