  "apiErrors.profileOwnerNameOnly": "শুধুমাত্র ব্যবসার মালিকই মালিকের নাম সেট করতে পারেন।",
  "apiErrors.profilePhotosApproveOwnerOnly": "শুধুমাত্র ব্যবসার মালিকই দলের ছবি অনুমোদন করতে পারেন।",
  "apiErrors.profilePhotosNoneWaiting": "সেই দলের সদস্যের কোনো ছবি অনুমোদনের অপেক্ষায় নেই।",
  "apiErrors.profileOwnerNameTooLong": "আপনার নাম ৮০ অক্ষর বা তার কম রাখুন।",
  "training.lessons.your-profile-photo.title": "আপনার প্রোফাইল ছবি",
  "training.lessons.your-profile-photo.step1": "আপনার ছবি আপনার নামের পাশে অ্যাপের শীর্ষে, স্টাফ পেজে এবং আপনার বার্তাগুলির পাশে দেখা যায় — মালিক এটি অনুমোদন করার পরে। ততক্ষণ পর্যন্ত শুধু আপনার নামের আদ্যক্ষর দেখা যায়।",
  "training.lessons.your-profile-photo.step2": "সেটিংস খুলুন এবং আপনার প্রোফাইল ছবি খুঁজুন। নিজের একটি ছবি বেছে নিন এবং পাঠান। এটি অনুমোদনের জন্য মালিকের কাছে যায় — অপেক্ষা করার সময় এটি কোথাও দেখা যায় না।",
  "training.lessons.your-profile-photo.step3": "মালিক এটি অনুমোদন করলে আপনার ঘণ্টা বাজে এবং আপনার ছবি দেখা যেতে শুরু করে। এটি অনুমোদিত না হলে, একটি ভিন্ন ছবি বেছে নিন এবং তার পরিবর্তে সেটি পাঠান।",
  "training.lessons.your-profile-photo.step4": "আপনার ছবি পরিবর্তন করাও একইভাবে কাজ করে: নতুনটি অনুমোদনের অপেক্ষায় থাকে, এবং নতুনটি অনুমোদিত না হওয়া পর্যন্ত আপনার বর্তমান ছবিটি জায়গায় থাকে। কোনো পরিবর্তন অনুমোদিত না হলে, আপনি আপনার অন্য ছবিটি রেখে দেন।",
  "training.lessons.owner-profile-photos.title": "প্রোফাইল ছবি এবং আপনার নাম",
  "training.lessons.owner-profile-photos.step1": "প্রত্যেক ব্যক্তির ছবি তাদের নামের পাশে অ্যাপের শীর্ষে, আপনার স্টাফ পেজে এবং তাদের বার্তাগুলির পাশে দেখা যায়। আপনি অনুমোদন না করা পর্যন্ত দলের কোনো সদস্যের ছবি কোথাও দেখা যায় না — অনুমোদন শুধুমাত্র আপনার, এবং কেউ নিজের ছবি নিজে অনুমোদন করতে পারে না।",
  "training.lessons.owner-profile-photos.step2": "কেউ ছবি পাঠালে আপনার ঘণ্টা বাজে। এটি দেখতে স্টাফ পেজ খুলুন, তারপর অনুমোদন করুন বা অনুমোদন করবেন না বেছে নিন। আপনি যদি এটি অনুমোদন না করেন, তবে সেই ব্যক্তিকে অন্য একটি ছবি বেছে নিতে বলা হয়।",
  "training.lessons.owner-profile-photos.step3": "কোনো ব্যক্তি তার ছবি পরিবর্তন করলে, নতুনটি একইভাবে আপনার অনুমোদনের অপেক্ষায় থাকে। তার বর্তমান ছবিটি অপেক্ষা করার সময় জায়গায় থাকে — এবং আপনি পরিবর্তনটি অনুমোদন না করলে থেকে যায়।",
  "training.lessons.owner-profile-photos.step4": "আপনার নিজের ছবির কোনো অনুমোদনের প্রয়োজন নেই: সেটিংসে, আপনার প্রোফাইল ছবির অধীনে এটি সেট করুন। একই কার্ডে আপনার নামও থাকে — সেখানে আপনি যে নামটি সেট করেন তা সর্বত্র মালিক শব্দটির জায়গা নেয় যেখানে আপনার দল এটি দেখে, অ্যাপে এবং বার্তাগুলিতে।",
  "payroll.dd.corrected": "সংশোধিত ফর্ম",
  "payroll.dd.correctedDone": "আপনার সংশোধিত বিবরণ মালিকের কাছে পাঠানো হয়েছে।",
  "payroll.dd.correctionNotice": "মালিক আপনার ফর্মটি আপনাকে ফেরত পাঠিয়েছেন যাতে আপনি তা সংশোধন করতে পারেন। প্রতিটি সংখ্যা যাচাই করুন, স্বাক্ষর করুন এবং আবার পাঠান।",
  "payroll.dd.correctionWaiting": "ফেরত পাঠানো হয়েছে — তার সংশোধিত ফর্মের অপেক্ষায়",
  "payroll.dd.fixHelp": "যদি কোনো সংখ্যা ভুল হয়, আপনার বিবরণ সংশোধন করুন এবং ফর্মটি আবার পাঠান। আপনার নতুন স্বাক্ষরিত ফর্ম পুরনোটির জায়গা নেয়, এবং মালিককে জানানো হয় যে এটি সংশোধন করা হয়েছে।",
  "payroll.dd.fixMistake": "একটি ভুল সংশোধন করুন",
