  "payroll.dd.form.ownerOnlyNote": "শুধুমাত্র আপনি, মালিক, এই ফর্মটি খুলতে পারেন। এতে পুরো ব্যাংক নম্বর এবং সদস্যের স্বাক্ষর দেখা যায়।",
