  "payroll.dd.signHelp": "আপনার নাম লিখুন, তারপর বেছে নিন আপনার স্বাক্ষর কেমন দেখাবে। এটিই আপনার ইলেকট্রনিক স্বাক্ষর — এটি আপনার ডাইরেক্ট ডিপোজিট ফর্মে ঠিক এখানে যেমন দেখানো হয়েছে তেমনভাবেই বসানো হয়।",
