  "payroll.profile.noAddress": "এখনও কোনো বাড়ির ঠিকানা নথিভুক্ত নেই।",
  "payroll.profile.note": "এই বিবরণ আপনার বেতন ও করের ফর্মের জন্য ব্যবহৃত হয়, এবং শুধুমাত্র আপনি এখানে এগুলি দেখতে পারেন। যদি কিছুর পরিবর্তন দরকার হয়, মালিক বা আপনার ব্যবস্থাপককে বলুন — তারাই এগুলি হালনাগাদ করতে পারেন।",
