  "training.lessons.owner-dd-setup.step5": "যা পৌঁছায় তা একটি সিল করা, স্বাক্ষরিত ফর্ম: পেরোলে ওই ব্যক্তির সারি থেকে আপনি এটি খুলে পুরো নম্বর পড়তে পারেন, প্রিন্ট করতে পারেন বা একটি কপি সংরক্ষণ করতে পারেন — আপনি কখনই এটি সম্পাদনা করতে পারবেন না। যদি কোনো নম্বর ভুল মনে হয়, ফর্মটি ফেরত পাঠান: ব্যক্তি নিজেই তা সংশোধন করে আবার স্বাক্ষর করেন, তার সংশোধিত ফর্ম পুরনোটির জায়গা নেয়, এবং আগের ফর্মটি তার প্রতিস্থাপনের তারিখসহ রেকর্ডে থেকে যায়।",
  "payroll.profile.ownerNote": "এগুলো আপনার নিজের বিবরণ যা ফাইলে আছে, আপনার অ্যাকাউন্ট থেকে। শুধুমাত্র আপনিই এখানে এগুলো দেখতে পারেন — এবং যেহেতু এগুলো আপনার, বদলালেই আপনি এখানেই আপডেট করতে পারেন।",
