  "staffLib.area.clockAccess": "ঘড়ি বোর্ড ও কল-ইন",
  "staff.memberDialog.clockAccessHint": "শুধুমাত্র ম্যানেজারদের জন্য — দুটি আলাদা টিক। ঘড়ি বোর্ড ও মিস হওয়া ঘড়ি-আউট এই ম্যানেজারকে দলের ঘড়ি এন্ট্রি দেখতে এবং স্টাফ পেজ থেকে সময়ের এন্ট্রি সংশোধন করতে দেয়। কল-ইন এই ম্যানেজারকে কল-ইন উইন্ডো খুলতে দেয়, কাউকে তখন কাজ করতে দেওয়া যখন তার শিফট নির্ধারিত নয়। এই টিকগুলি স্টাফদের জন্য কিছু করে না।",
  "workforce.clockGate.closed": "এখন আপনার কাজের সময় নির্ধারিত নেই, এবং আপনার জন্য কোনো কল-ইন উইন্ডো খোলা নেই।",
  "workforce.clockGate.closedNext": "এখন আপনার কাজের সময় নির্ধারিত নেই, এবং আপনার জন্য কোনো কল-ইন উইন্ডো খোলা নেই। আপনার পরের শিফট শুরু হয় {when}।",
  "workforce.callIn.openForYou": "আপনাকে ডাকা হয়েছে — কোনো শিফট এই সময়টুকু না ঢাকলেও আপনি এখন ক্লক ইন করতে পারেন।",
