  "staff.callIn.title": "কল-ইন ও মিস করা ক্লক-আউট",
  "staff.callIn.desc": "কারো শিফট নির্ধারিত না থাকলে তাকে ডাকুন, এবং ক্লক-আউট ভুলে গেলে সময়ের এন্ট্রি ঠিক করুন। একটি কল-ইন উইন্ডো সেই ব্যক্তি ক্লক আউট না করা পর্যন্ত খোলা থাকে।",
