  "apiErrors.clockGate.notScheduled": "এখন আপনার কাজের সময় নির্ধারিত নেই, এবং আপনার জন্য কোনো কল-ইন উইন্ডো খোলা নেই।",
  "apiErrors.clockAdmin.callinsNotGranted": "শুধুমাত্র মালিক, অথবা যে ম্যানেজারকে মালিক কল-ইনের জন্য বিশ্বাস করেছেন, তিনিই এটি করতে পারেন।",
  "apiErrors.clockAdmin.boardNotGranted": "শুধুমাত্র মালিক, অথবা যে ম্যানেজারকে মালিক ঘড়ি বোর্ড ও মিস হওয়া ঘড়ি-আউটের জন্য বিশ্বাস করেছেন, তিনিই এটি করতে পারেন।",
  "apiErrors.clockAdmin.ownerOnlyForManager": "একজন ম্যানেজারের কল-ইন ও সময়ের এন্ট্রি শুধুমাত্র মালিকই পরিচালনা করতে পারেন।",
  "apiErrors.clockFix.outBeforeIn": "ক্লক-আউটের সময় ক্লক-ইনের সময়ের পরে হতে হবে।",
  "apiErrors.clockFix.breakOutside": "বিরতির সময়গুলো ক্লক-ইন ও ক্লক-আউট সময়ের মাঝে হতে হবে।",
  "apiErrors.clockFix.invalidTime": "প্রতিটি সময় বৈধ তারিখ ও সময় হিসেবে পাঠান।",
  "apiErrors.notFound.timeEntryFound": "সময়ের এন্ট্রি পাওয়া যায়নি।",
  "training.lessons.mgr-clock-callin.title": "কল-ইন ও ঘড়ি সংশোধন",
  "training.lessons.mgr-clock-callin.step1": "মালিক একজন ম্যানেজারকে দুটি আলাদা টিক দিতে পারেন। কল-ইন দিয়ে আপনি একজন স্টাফ সদস্যের জন্য কল-ইন উইন্ডো খুলতে পারেন, এবং ঘড়ি বোর্ড ও মিস হওয়া ঘড়ি-আউট দিয়ে আপনি দলের ঘড়ি বোর্ড দেখতে এবং স্টাফ পেজ থেকে সময়ের এন্ট্রি সংশোধন করতে পারেন। প্রতিটি টিক নিজে নিজেই কাজ করে — একজন ম্যানেজার একটি ছাড়া অন্যটি রাখতে পারেন।",
  "training.lessons.mgr-clock-callin.step2": "একটি কল-ইন উইন্ডো একজন ব্যক্তিকে তখন সাইন ইন ও ক্লক ইন করতে দেয় যখন কোনো শিফট তাকে ঢাকে না। স্টাফ পেজে, কল-ইন ও মিস করা ক্লক-আউট কার্ড থেকে এটি খুলুন।",
  "training.lessons.mgr-clock-callin.step3": "উইন্ডোটি সেই ব্যক্তি ক্লক আউট না করা পর্যন্ত খোলা থাকে — তারপর সাইন-আউটের আগের স্বাভাবিক 10-মিনিটের ছাড় আসে — অথবা আপনি বা মালিক আগেই এটি বন্ধ না করা পর্যন্ত। কিছুই নিজে থেকে এটি বন্ধ করে না।",
  "training.lessons.mgr-clock-callin.step4": "যখন কেউ ক্লক আউট করতে ভুলে যায়, নির্ধারিত শিফট শেষ হলেই তার এন্ট্রি স্টাফ পেজে ও পেরোলে চিহ্নিত হয়, এবং আপনি ও মালিক নোটিফিকেশন পান। এন্ট্রিটি সংশোধন না হওয়া পর্যন্ত গণনা চলতে থাকে।",
  "training.lessons.mgr-clock-callin.step5": "স্টাফ পেজ থেকে এন্ট্রি সংশোধন করুন: ক্লক-ইন, ক্লক-আউট এবং বিরতির সময় নির্ধারণ করুন। একজন ম্যানেজার শুধুমাত্র স্টাফদের এন্ট্রি সংশোধন করেন — ম্যানেজারের নিজের এন্ট্রি মালিক সংশোধন করেন।",
  "staffLib.perm.staffDocuments": "কর্মীদের নথি",
  "staffLib.area.documentsAccess": "কর্মীদের নথি",
  "staff.memberDialog.documentsAccessHint": "শুধুমাত্র ম্যানেজারদের জন্য — এই টিক দিয়ে, এই ম্যানেজার কর্মী সদস্যদের নথির ফাইল খুলতে পারবেন: প্রতিটি ব্যক্তির জন্য রাখা কাগজপত্র, যেমন W-4 ফর্ম, চাকরির আবেদন এবং পরিচয়পত্রের কপি। প্রথমে আপনার কাছে নিশ্চিতকরণ চাওয়া হবে — এই ফাইলগুলিতে সামাজিক নিরাপত্তা নম্বর এবং জন্ম তারিখ থাকে। এই টিক কর্মীদের জন্য কিছু করে না।",
  "staff.documentsWarning.body": "এই ব্যক্তি আপনার কর্মী সদস্যদের সম্পর্কে গোপনীয় তথ্য দেখতে পারবেন, যার মধ্যে সামাজিক নিরাপত্তা নম্বর এবং জন্ম তারিখ রয়েছে।",
  "staff.documentsWarning.confirm": "হ্যাঁ, আমি বুঝেছি",
