  "apiErrors.recipeCircle": "এই রেসিপিগুলি একটি বৃত্ত তৈরি করবে — একটি ডিশ অন্য ডিশগুলির মধ্য দিয়ে হলেও নিজের উপাদান হতে পারে না।",
  "apiErrors.recipeAlreadyActive": "সেই ডিশের একটি সক্রিয় রেসিপি ইতিমধ্যে আছে। আগে অন্য রেসিপিটিকে খসড়ায় ফিরিয়ে নিন।",
