  "plansLib.businessIncludes.restaurantOps": "রেস্টুরেন্ট পরিচালনা — ত্রিমুখী মিলসহ সরবরাহকারীর ইনভয়েস, অপচয়ের লগ, মেয়াদের তারিখ ও অ্যালার্জেন ছক",
  "plansLib.businessIncludes.restaurantDaily": "রেস্টুরেন্টের দৈনন্দিন সরঞ্জাম — তাপমাত্রার লগ, শেষ হয়ে যাওয়া পণ্যের বোর্ড, প্রস্তুতির শিট, মেনু ইঞ্জিনিয়ারিং, পার্থক্য ও হিসাব রপ্তানি",
  "plansLib.businessIncludes.restaurantKitchen": "রেস্টুরেন্ট, রান্নাঘর ও রেসিপি — স্বয়ংক্রিয় উপাদান কাটা ও ডিশের প্রকৃত খরচসহ রেসিপি, প্রস্তুতির শিট, ব্যাচ উৎপাদন ও মেনু ইঞ্জিনিয়ারিং",
  "plansLib.businessIncludes.restaurantStock": "রেস্টুরেন্ট, মজুদ ও অর্ডার — পার স্তর, সরবরাহকারীর অর্ডার গাইড ও অবস্থানগুলোর মধ্যে স্থানান্তর, পাশাপাশি তাক অনুযায়ী গণনা শীট",
  "plansLib.businessIncludes.restaurantMoney": "রেস্টুরেন্ট, ইনভয়েস ও অর্থ — ত্রিমুখী মিলসহ সরবরাহকারীর ইনভয়েস, দামের সতর্কতা, পার্থক্য ও হিসাব রপ্তানি, পাশাপাশি সরবরাহকারী ক্রেডিট মেমো",
  "plansLib.businessIncludes.restaurantSafety": "রেস্টুরেন্ট, খাদ্য নিরাপত্তা — তাপমাত্রার লগ, আগে মেয়াদ শেষ হবে আগে ক্রমে মেয়াদের তারিখ, তারিখের লেবেল ও অ্যালার্জেন ছক, এবং খাদ্য নিরাপত্তা ফাইলের জন্য ভরা তাপমাত্রা লগ",
