  "variance.subtitle": "পণ্য অনুযায়ী: রেসিপি অনুযায়ী শেলফ থেকে যা যাওয়া উচিত ছিল, তার পাশে কর্মীদের খাবার, অপচয়, এবং বেরিয়ে যাওয়া বাকি সবকিছু। যা ব্যাখ্যাতীত থাকে, সেটাই গিয়ে ব্যাখ্যা করার ফাঁক।",
