  "logBook.subtitle": "প্রতিটি শিফটের আনুষ্ঠানিক রেকর্ড: কী ঘটেছিল, কী হস্তান্তর করা হয়েছিল এবং পরের ব্যক্তির কী জানা দরকার। দলের সবাই এটি পড়তে এবং এতে যোগ করতে পারে।",
