  "exportsLib.restaurantLedger.title": "রেস্টুরেন্টের খাতা",
  "exportsLib.restaurantLedger.description": "গৃহীত কেনাকাটা, অপচয়, কর্মীদের খাবার ও রেসিপির হ্রাস এক খাতায়: বিভাগ, তারিখ, পণ্য, পরিমাণ, একক খরচ, মোট খরচ ও সূত্র।",
