  "print.colScore": "স্কোর",
  "plansLib.includes.recordPrints": "কাগজে রেকর্ড — সাপ্তাহিক সময়সূচি, বেতন রেজিস্টার, টাইমশিট, প্রশিক্ষণ রেকর্ড, নীতি ও শর্তাবলি, কর্মীদের তালিকা এবং মূল্য তালিকা, ভরা অবস্থায় বা হাতে পূরণের জন্য ফাঁকা ছাপানো",
  "training.lessons.staff-record-prints.title": "কাগজে আপনার রেকর্ড",
  "training.lessons.staff-record-prints.step1": "অ্যাপের প্রায় প্রতিটি রেকর্ডের এখন ডকুমেন্ট স্টাইল স্টুডিওতে একটি কাগজের যমজ আছে: সাপ্তাহিক সময়সূচি, বেতন রেজিস্টার, টাইমশিট, প্রশিক্ষণ রেকর্ড, আপনার দোকানের নীতি ও শর্তাবলি, কর্মীদের তালিকা এবং পণ্য ও মূল্য তালিকা — এবং Business প্ল্যানে, সরবরাহকারী ডিরেক্টরি ও ভরা তাপমাত্রা লগ। প্রতিটি আপনার সংরক্ষিত ডকুমেন্ট স্টাইলে, আপনার ব্যবসার ভাষায়, আপনার তারিখ আপনার মতো করে লিখে ছাপা হয়।",
  "training.lessons.staff-record-prints.step2": "প্রতিটি কাগজ সেখানেই পাবেন যেখানে তার রেকর্ড থাকে। কর্মী পৃষ্ঠায়, সময়সূচি ট্যাব সপ্তাহটি ছাপে তাদের সবার জন্য যাদের আপনি দেখতে পান, আর সময় ঘড়ি ট্যাব তার এন্ট্রি থেকে টাইমশিট ছাপে। ছাপা কেবল তাই দেখায় যা আপনি সেই স্ক্রিনে ইতিমধ্যে দেখতে পান — ছাপা কখনো কারো দৃষ্টি বাড়ায় না।",
  "training.lessons.staff-record-prints.step3": "বেতন পৃষ্ঠায়, একটি বেতন মেয়াদের প্রিভিউ দেখুন এবং রেজিস্টারটি ছাপুন: প্রতিটি ব্যক্তি, তাদের ঘণ্টা, মোট, কর্তন ও নিট এক শিটে মজুরি ফাইলের জন্য। প্রশিক্ষণ পৃষ্ঠায়, দল বিভাগ প্রশিক্ষণ রেকর্ড ছাপে — কে কী শেষ করেছে, কুইজ স্কোর ও তারিখসহ।",
  "training.lessons.staff-record-prints.step4": "আপনার দোকানের নীতি ও শর্তাবলি সেটিংস থেকে ছাপা হয়, ঠিক যেমন আপনি লিখেছেন, নতুন কর্মীর হাতে বা দেয়ালের জন্য প্রস্তুত। কর্মী পৃষ্ঠা এক পৃষ্ঠার তালিকা ছাপে, পণ্য পৃষ্ঠা মূল্য তালিকা ছাপে, এবং Business-এ সরবরাহকারী পৃষ্ঠা ডিরেক্টরি ও তাপমাত্রা লগ পৃষ্ঠা ভরা লগটি খাদ্য নিরাপত্তা ফাইলের জন্য ছাপে।",
  "training.lessons.staff-record-prints.step5": "পরিবর্তে হাতে পূরণের শিট চাই? প্রিন্ট সেন্টারের ফাঁকা ফর্মগুলিতে এখন এই প্রতিটি কাগজের একটি ফাঁকা যমজ আছে, দুটি প্ল্যানেই: একটি ছাপুন, কলম দিয়ে পূরণ করুন, এবং ছাপানোগুলোর পাশে ফাইল করুন।",
  "ageCheck.title": "বয়স যাচাই",
  "ageCheck.intro": "ড্রাইভিং লাইসেন্স বা পরিচয়পত্রের পেছনের বারকোডটি স্ক্যান করুন। আপনি একটি মাত্র উত্তর পাবেন — একটি সবুজ চিহ্ন বা একটি লাল চিহ্ন — এবং অ্যাপটি স্ক্যান থেকে কিছুই রাখে না: কোনো নাম, কোনো নম্বর, কোনো জন্মতারিখ, কিছুই লেখা থাকে না।",
  "ageCheck.scanPrompt": "ক্যামেরাটি লাইসেন্স বা কার্ডের পেছনের বারকোডের দিকে ধরুন।",
