  "ageCheck.pass": "বয়স পূর্ণ হয়েছে — বিক্রিটি এগিয়ে যেতে পারে।",
  "ageCheck.fail": "বয়স পূর্ণ হয়নি — এই বিক্রিটি করবেন না।",
  "ageCheck.expired": "এই কার্ডটির মেয়াদ শেষ — এটি পাস করে না।",
  "ageCheck.unreadable": "ওই কোডটি এমন কোনো পরিচয়পত্রের বারকোড নয় যা আমরা পড়তে পারি। লাইসেন্সের পেছনের বারকোডটি চেষ্টা করুন।",
  "ageCheck.checkAnother": "আরেকটি যাচাই করুন",
  "ageCheck.back": "পণ্য স্ক্যানিংয়ে ফিরে যান",
  "ageCheck.keepsNothing": "এই স্ক্যান থেকে কিছুই সংরক্ষিত, পাঠানো বা রেকর্ড করা হয় না। উত্তরটাই সব, এবং এই পর্দা ছাড়লেই তা মুছে যায়।",
  "settings.ageLines.title": "বয়সের সীমা",
  "settings.ageLines.description": "প্রতিটি ধরনের বিক্রির জন্য গ্রাহকের যে বয়সে পৌঁছাতে হবে, স্ক্যান পাতার বয়স যাচাই তা-ই ব্যবহার করে। এই সীমাগুলো আপনারই নির্ধারণের — আপনার ব্যবসা যেখানে, সেখানকার আইন অনুযায়ী সেগুলো সাজান। অ্যাপটি মদের জন্য 21, তামাকের জন্য 21 এবং অন্যান্য বয়স-সীমাবদ্ধ পণ্যের জন্য 18 দিয়ে শুরু করে।",
  "settings.ageLines.alcohol": "মদ — সর্বনিম্ন বয়স",
  "settings.ageLines.tobacco": "তামাক — সর্বনিম্ন বয়স",
  "settings.ageLines.other": "অন্যান্য বয়স-সীমাবদ্ধ পণ্য — সর্বনিম্ন বয়স",
  "plansLib.includes.ageCheck": "লাইসেন্স স্ক্যানে বয়স যাচাই — কোনো পরিচয়পত্রের পেছন স্ক্যান করে সবুজ বা লাল চিহ্ন পান, কার্ড থেকে কিছুই রাখা হয় না",
  "training.lessons.scanner-age-check.title": "লাইসেন্স স্ক্যান দিয়ে বয়স যাচাই",
  "training.lessons.scanner-age-check.step1": "কিছু পণ্য কেবল নির্দিষ্ট বয়সের বেশি গ্রাহকদের কাছেই বিক্রি করা যায়। স্ক্যান পাতায় বয়স যাচাই খুলুন, কী বিক্রি হচ্ছে বেছে নিন — মদ, তামাক বা অন্যান্য বয়স-সীমাবদ্ধ পণ্য — তারপর গ্রাহকের ড্রাইভিং লাইসেন্স বা পরিচয়পত্রের পেছনের বারকোডটি স্ক্যান করুন।",
  "training.lessons.scanner-age-check.step2": "উত্তরটি দুটি চিহ্নের একটি। সবুজ চিহ্ন মানে গ্রাহকের বয়স পূর্ণ হয়েছে এবং বিক্রিটি এগিয়ে যেতে পারে। লাল চিহ্ন মানে ওই সীমার বয়সে সে পৌঁছায়নি, অথবা কার্ডটির মেয়াদ শেষ — যেভাবেই হোক, বিক্রিটি হওয়া উচিত নয়।",
  "training.lessons.scanner-age-check.step3": "অ্যাপটি স্ক্যান থেকে কিছুই রাখে না। কোনো নাম, লাইসেন্স নম্বর বা জন্মতারিখ কোথাও সংরক্ষিত, পাঠানো বা লেখা হয় না: যাচাইটি একটি মাত্র প্রশ্নের উত্তর দিয়ে মুছে যায়। যাচাই করা কার্ডের কোনো তালিকা ফিরে দেখার জন্য নেই — এটা ইচ্ছাকৃত।",
  "training.lessons.scanner-age-check.step4": "বয়সের সীমাগুলো মালিকের, যিনি সেটিংসে ব্যবসা যেখানে সেখানকার আইন অনুযায়ী সেগুলো সাজান। সেগুলো জায়গাভেদে এবং অ্যাপের শুরুর সীমা থেকে আলাদা হতে পারে, এবং যাচাইটি সবসময় আপনি যে ব্যবসায় আছেন তার মালিকের সীমা অনুসরণ করে।",
  "training.lessons.scanner-age-check.step5": "কোডটি পড়া না গেলে পর্দা তা স্পষ্ট করে বলে। বারকোডটি মুছে আবার চেষ্টা করুন, অথবা অন্য কার্ড দেখতে চান। যে কোড পরিচয়পত্রের বারকোড নয়, তা কখনো সবুজ চিহ্ন পায় না।",
  "training.heading.general": "সাধারণ প্রশিক্ষণ",
  "training.heading.restaurant": "রেস্তোরাঁ প্রশিক্ষণ",
  "training.own.title": "আপনার নিজের প্রশিক্ষণ যোগ করুন",
  "training.own.help": "আপনার নিজের একটি প্রশিক্ষণ লিখুন — আপনার নিরাপত্তা নিয়ম, আপনার সতর্কতা, আপনার কাজ করার ধরন — তারপর এর কুইজ তৈরি করুন এবং যাদের এটি নেওয়া উচিত তাদের টিক দিন। আপনার প্রশিক্ষণ শুধু এই ব্যবসাতেই থাকে; অন্য ব্যবসার কেউ কখনো তা দেখে না।",
