  "training.own.questionsHint": "এই প্রশিক্ষণের কুইজ তৈরি করুন। বহুনির্বাচনী ও লিখিত-উত্তরের প্রশ্ন স্বাধীনভাবে মেশান — কতটি লিখবেন তার কোনো সীমা নেই।",
