  "training.own.pendingReview": "মালিকের কাছে মূল্যায়নের জন্য",
  "training.own.markPass": "পাস হিসেবে চিহ্নিত করুন",
  "training.own.sectionTitle": "আপনার মালিকের কাছ থেকে প্রশিক্ষণ",
  "training.own.sectionHelp": "আপনার মালিক এই দোকানের জন্য এই প্রশিক্ষণগুলি লিখেছেন। প্রতিটি পড়ুন, তারপর আপনার মালিকের প্রশ্নের উত্তর দিন।",
  "training.own.read": "প্রশিক্ষণ",
  "training.own.noMaterial": "মালিক এখনো প্রশিক্ষণের লেখা যোগ করেননি।",
  "training.own.pendingNote": "আপনার উত্তর মালিকের কাছে আছে। মালিক এটিকে পাস চিহ্নিত করলে এই প্রশিক্ষণ সম্পূর্ণ গণনা হয়।",
  "plansLib.includes.ownTraining": "আপনার নিজের প্রশিক্ষণ যোগ করুন — আপনার দলের জন্য নিজের প্রশিক্ষণ ও কুইজ লিখুন",
  "training.lessons.owner-own-training.title": "আপনার নিজের প্রশিক্ষণ যোগ করা",
  "training.lessons.owner-own-training.step1": "প্রশিক্ষণ পৃষ্ঠার একেবারে শেষে আপনার নিজের প্রশিক্ষণ যোগ করুন বাক্সটি আছে। এটি খুলুন, একটি নতুন প্রশিক্ষণ শুরু করুন, এবং এটিকে একটি শিরোনাম দিন — আপনার নিরাপত্তা নিয়ম, আপনার সতর্কতা, আপনার কাজ করার ধরন।",
  "training.lessons.owner-own-training.step2": "প্রশিক্ষণটি বাক্সে আপনার নিজের ভাষায় লিখুন, অথবা এর বদলে ফাইল হিসেবে আপলোড করুন — PDF, টেক্সট, Word বা OpenDocument ফাইল। টাইপ করা লেখা সংরক্ষিত ফাইলের জায়গা নেয়, এবং ফাইল টাইপ করা লেখার জায়গা নেয়।",
  "training.lessons.owner-own-training.step3": "এর নিচে এর কুইজ তৈরি করুন: যত প্রশ্ন চান, বহুনির্বাচনী ও লিখিত-উত্তর স্বাধীনভাবে মেশানো। লিখিত প্রশ্নের জন্য, আপনি যে উত্তর আশা করেন তা লিখুন; বহুনির্বাচনীর জন্য, সঠিকটি চিহ্নিত করুন।",
  "training.lessons.owner-own-training.step4": "পাসের রেখা নির্ধারণ করুন, এবং বেছে নিন লিখিত উত্তর কীভাবে বিচার হবে: আপনার উত্তর-চাবি দিয়ে প্রায় হুবহু যাচাই করা হবে, নাকি আপনার কাছে পাঠানো হবে যাতে আপনি পাস চিহ্নিত করেন বা ফেরত পাঠান। তারপর ঠিক করে টিক দিন দলের কোন সদস্যরা এই প্রশিক্ষণ নেয় — শুধু তারাই এটি দেখে।",
  "training.lessons.owner-own-training.step5": "আপনি যে প্রতিটি প্রশিক্ষণ সংরক্ষণ করেন তা বাক্সে নিজের প্রশ্ন, রেখা ও টিক নিয়ে আলাদা থাকে, এবং আপনি যত চান যোগ করতে পারেন। ফলাফল প্রতিটি প্রশিক্ষণের নিচে বাক্সে আসে; কোনো প্রশিক্ষণ তখনই সম্পূর্ণ গণনা হয় যখন সার্ভার একটি পাস করা প্রচেষ্টা যাচাই করে — অথবা, মূল্যায়ন মোডে, যখন আপনি এটিকে পাস চিহ্নিত করেন।",
  "apiErrors.ownTrainingOwnerWrites": "এই প্রশিক্ষণগুলি শুধু মালিক লেখেন।",
