  "apiErrors.ownTrainingWrittenMode": "লিখিত উত্তর চাবি দিয়ে যাচাই করা হয় অথবা মালিকের কাছে পাঠানো হয়।",
  "print.pool.title": "বারকোড তৈরি করুন",
  "print.pool.intro": "পণ্য থাকার আগেই বারকোড তৈরি করুন। সেগুলি ছাপুন, যেসব পণ্যের নিজস্ব বারকোড নেই সেগুলিতে লাগান, এবং পরে কোনোটি স্ক্যান হলে অ্যাপ কোডটি চিনবে ও পণ্য যোগ করার প্রস্তাব দেবে।",
  "print.pool.countLabel": "আপনার কতগুলি বারকোড দরকার?",
  "print.pool.generate": "তৈরি করুন",
