  "print.pool.failed": "সেই বারকোডগুলি তৈরি করা যায়নি। আবার চেষ্টা করুন।",
  "scan.pool.title": "আপনার নিজের ছাপানো বারকোডগুলির একটি",
  "scan.pool.body": "এটি এখনও আপনার দোকানের পণ্য নয় — এটি এমন একটি বারকোড যা আপনি আগেই ছাপিয়েছিলেন। আপনি কি এটি পণ্য হিসেবে যোগ করতে চান?",
  "plansLib.includes.barcodePool": "বারকোড পুল — আগেই বারকোড ছাপুন, তারপর প্রতিটি পণ্য তার বারকোড স্ক্যান হলেই যোগ করুন",
  "training.lessons.owner-barcode-pool.title": "পণ্যের আগে বারকোড ছাপানো",
  "training.lessons.owner-barcode-pool.step1": "কিছু পণ্যের নিজস্ব বারকোড থাকে না — হাতে তৈরি জিনিস, আপনার নিজের বইয়ের ব্যাগ, যা কিছু আপনি নিজে তৈরি বা একত্র করেন। প্রিন্ট বিভাগে বারকোড তৈরি করুন দরজা পণ্য থাকার আগেই কোড তৈরি করে।",
  "training.lessons.owner-barcode-pool.step2": "বলুন কতগুলি দরকার — কোনো সীমা নেই — আর অ্যাপ আপনার ব্যবসার বারকোড পুলে ঠিক ততগুলি নতুন কোড তৈরি করবে। সেগুলি শুধু আপনার ব্যবসার, কখনো দুবার দেওয়া হয় না, এবং সেগুলি তৈরি করলে কোনো পণ্য বা মজুত তৈরি হয় না।",
  "training.lessons.owner-barcode-pool.step3": "তৈরি হওয়ার মুহূর্তেই বেছে নিন: এখনই লেবেল হিসেবে ছাপুন, অথবা পরে ছাপার জন্য PDF হিসেবে সংরক্ষণ করুন। যেভাবেই হোক কোডগুলি পুলে থাকে, আর ছাপানো লেবেলগুলি পুলের সঙ্গে হুবহু মেলে।",
  "training.lessons.owner-barcode-pool.step4": "প্রতিটি জিনিস তৈরি করার সময় তাতে একটি লেবেল লাগান। অব্যবহৃত কোডগুলি পুলে শুধু অপেক্ষা করে — তাড়া নেই এবং সেগুলির মেয়াদ শেষ হয় না।",
  "training.lessons.owner-barcode-pool.step5": "লেবেল লাগানো কোনো জিনিস পরে স্ক্যান হলে অ্যাপ নিজের ছাপানো কোডটি চেনে এবং কোড আগেই ভরা অবস্থায় পণ্য যোগ করার প্রস্তাব দেয়। যোগ হয়ে গেলে সেই কোডটি ওই পণ্যের কোড হয়ে যায় এবং অন্য যেকোনো কোডের মতো স্ক্যান হয়।",
  "apiErrors.poolOwnerMints": "পুলের জন্য বারকোড শুধু মালিকই তৈরি করেন।",
  "apiErrors.poolCount": "বলুন আপনার কতগুলি বারকোড দরকার — একটি পূর্ণ সংখ্যা, এক বা তার বেশি।",
  "nav.checklists": "চেকলিস্ট",
  "plansLib.includes.checklists": "চেকলিস্ট — খোলা, বন্ধ করা, পরিষ্কার করা এবং আরও অনেক কিছু, ফোনে টিক দেওয়া, যেখানে গুরুত্বপূর্ণ সেখানে প্রমাণসহ",
  "staffLib.perm.checklistsManage": "চেকলিস্ট টেমপ্লেট ও দায়িত্ব",
