  "apiErrors.checklistsManage": "শুধু মালিক, বা মালিক যাকে চেকলিস্ট টেমপ্লেটের টিক দিয়েছেন, তিনিই চেকলিস্ট টেমপ্লেট বদলাতে পারেন।",
  "apiErrors.checklistProof": "এই আইটেমটিতে টিক দেওয়ার আগে এর প্রমাণ দরকার।",
  "apiErrors.checklistName": "চেকলিস্টটিকে একটি নাম দিন।",
  "apiErrors.checklistItems": "চেকলিস্টে অন্তত একটি আইটেম যোগ করুন।",
  "apiErrors.checklistUntick": "শুধু যিনি এই আইটেমে টিক দিয়েছেন, কোনো ম্যানেজার, বা মালিকই টিক তুলতে পারেন।",
  "training.lessons.staff-checklists.title": "একটি চেকলিস্টে কাজ করা",
  "training.lessons.staff-checklists.step1": "চেকলিস্ট হলো সেই তালিকা যা দিয়ে আপনার ব্যবসা চলে — খোলা, বন্ধ করা, পরিষ্কার করা, এবং মালিক যা যা ঠিক করেন। এগুলো চেকলিস্টে পাবেন: আজকের তালিকাগুলো একদম উপরে, টিক দেওয়ার জন্য প্রস্তুত।",
  "training.lessons.staff-checklists.step2": "কোনো আইটেমে তখনই টিক দিন যখন সত্যিই তা করে ফেলেছেন। প্রতিটি টিক লিখে রাখে কে করেছে এবং কখন, যাতে পরের ব্যক্তি — এবং বাড়িতে থাকা মালিক — দেখতে পারেন কী হয়েছে আর কী বাকি আছে।",
  "training.lessons.staff-checklists.step3": "কিছু আইটেম টিক দেওয়ার আগে প্রমাণ চায়: শেষ করা কাজের ছবি, কোনো কোডের স্ক্যান, বা লেখা তাপমাত্রা। প্রথমে প্রমাণ যোগ করুন, তারপর টিক দিন — তা ছাড়া আইটেমে টিক পড়বে না।",
  "training.lessons.staff-checklists.step4": "ভুল করে কিছুতে টিক দিয়ে ফেলেছেন? টিক তুলুন — কিন্তু শুধু নিজের টিকগুলো। কোনো ম্যানেজার বা মালিক যেকোনো কারো টিক তুলতে পারেন, কারণ টিক হলো নামসহ একটি রেকর্ড।",
  "training.lessons.staff-checklists.step5": "চেকলিস্টে কাজ করতে আপনার কখনো অনুমতি লাগে না। টেমপ্লেট তৈরি করা এবং সেগুলো কাকে দেওয়া হবে তা বেছে নেওয়া মালিকের কাজ, বা মালিক যাকে চেকলিস্ট টেমপ্লেটের টিক দিয়েছেন তার।",
