  "foodSafety.mock.item8": "বর্জ্য লগ হালনাগাদ আছে, ফেলে দেওয়া প্রতিটি জিনিসের কারণসহ।",
  "training.lessons.staff-food-safety.title": "খাদ্য নিরাপত্তা ফাইল রাখা",
  "training.lessons.staff-food-safety.step1": "খাদ্য নিরাপত্তা ফাইলটি রেস্তোরাঁ কর্নারের খাদ্য নিরাপত্তা তাকে থাকে: তাপমাত্রা লগ, শীতলকরণ, পুনরায় গরম করা এবং স্যানিটাইজার লগ, সনদ, নিরাপত্তা ডেটা শিট এবং পরিদর্শন প্যাকেট।",
  "training.lessons.staff-food-safety.step2": "সীমার বাইরের পাঠ ততক্ষণ সম্পূর্ণ নয় যতক্ষণ তার নোট না বলে আপনি কী করেছেন — আবার ঠান্ডা করেছেন, আবার গরম করেছেন, স্যানিটাইজার আবার বানিয়েছেন, ফেলে দিয়েছেন। নোট নেই, সংরক্ষণ নেই: এন্ট্রিটি দাঁড়ায় না।",
  "training.lessons.staff-food-safety.step3": "শীতলকরণ, পুনরায় গরম করা এবং স্যানিটাইজার পরীক্ষা তাপমাত্রার মতো লগ করুন: কী পরীক্ষা করেছেন, পাঠ, এবং মিস হলে সংশোধনমূলক পদক্ষেপ।",
  "training.lessons.staff-food-safety.step4": "সনদগুলো মেয়াদ শেষের আগে সতর্ক করে। আপনারটি সতর্ক করলে মালিককে বলুন — এবং যে কেউ যেকোনো সময় তাদের তাকে নিরাপত্তা ডেটা শিট পড়তে পারে।",
  "training.lessons.staff-food-safety.step5": "পরিদর্শনের আগে — অথবা যেকোনো সময় — খাদ্য নিরাপত্তা তাক থেকে মক পরিদর্শন চালান এবং পরিদর্শকের তারিখের জন্য পরিদর্শন-প্রস্তুত প্যাকেট ছাপুন।",
