  "plansLib.businessIncludes.guestMenuPage": "রেস্তোরাঁ, অতিথি মেনু পৃষ্ঠা — আপনার পদ, দাম ও অ্যালার্জি রেকর্ড থেকে শেয়ারযোগ্য মেনু",
