  "training.lessons.staff-kitchen-menu.title": "রান্নাঘরের ডিসপ্লে ও অতিথি মেনু দিয়ে রান্না",
  "training.lessons.staff-kitchen-menu.step1": "রান্নাঘর ও রেসিপি তাক থেকে রান্নাঘরের ডিসপ্লে খুলুন এবং যে রেসিপি রাঁধছেন তা বেছে নিন।",
  "training.lessons.staff-kitchen-menu.step2": "কয়টি ব্যাচ বানাচ্ছেন তা ছুঁয়ে বলুন। পর্দার প্রতিটি পরিমাণ সেই অনুযায়ী হবে — মুখস্থ নয়, পর্দা দেখে রাঁধুন।",
  "training.lessons.staff-kitchen-menu.step3": "ডিসপ্লে রেসিপির ছবি, আপনার ব্যাচ সংখ্যা অনুযায়ী উপকরণ এবং ক্রমানুসারে ধাপ দেখায়।",
  "training.lessons.staff-kitchen-menu.step4": "অতিথি মেনু শুধু সেই পদগুলো দেখায় যেগুলোতে মালিক টিক দিয়েছেন। দাম ও অ্যালার্জির চিহ্ন রেকর্ড থেকে আসে, দ্বিতীয়বার লিখে কখনো নয়।",
  "training.lessons.staff-kitchen-menu.step5": "মেনুর লিংক অতিথিদের সঙ্গে শেয়ার করুন বা মেনু ছাপুন। পড়তে অতিথিদের অ্যাকাউন্ট লাগে না।",
