  "training.lessons.staff-equipment.title": "যন্ত্রপাতির রেকর্ড এবং ত্রুটি জানানো",
  "training.lessons.staff-equipment.step1": "আপনার ব্যবসার প্রতিটি মেশিনের যন্ত্রপাতিতে নিজের পৃষ্ঠা আছে: কবে কেনা, ওয়ারেন্টি কবে শেষ, কে সার্ভিস করে, এবং তার সাথে যা কিছু ঘটেছে।",
  "training.lessons.staff-equipment.step2": "কিছু নষ্ট হলে, মেশিনেই তা জানান। বলুন কী নষ্ট হয়েছে, এবং পারলে সমস্যার ছবি যোগ করুন — প্রতিবেদনটি আপনার নাম ও সময়সহ মেশিনের ইতিহাসে যায়।",
  "training.lessons.staff-equipment.step3": "আপনি ত্রুটি জানাতে পারবেন শুধু যদি মালিক আপনাকে ত্রুটি জানানোর টিক দিয়ে থাকেন। বোতামটি না থাকলে মালিক বা ব্যবস্থাপককে বলুন, তারা আপনার জন্য দরজা খুলে দেবেন।",
  "training.lessons.staff-equipment.step4": "রক্ষণাবেক্ষণ কাজের — পরিষ্কার, ডিস্কেলিং, সার্ভিস — নির্ধারিত তারিখ থাকে। যন্ত্রপাতির পৃষ্ঠা দেখায় কী বাকি ও কী মেয়াদোত্তীর্ণ, যাতে কিছু নীরবে পিছিয়ে না যায়।",
  "training.lessons.staff-equipment.step5": "মেরামত ও তার খরচ লেখেন মালিক বা ব্যবস্থাপক। আপনার প্রতিবেদনে মেরামত লেখা হলে, ত্রুটিটি মেশিনের ইতিহাসে ঠিক হয়েছে বলে দেখায়।",
  "nav.tipPooling": "টিপ পুল",
  "plansLib.businessIncludes.tipPooling": "টিপ পুল ও টিপ রেকর্ড — পুলটি আপনার মতো করে ভাগ করুন এবং বছরের টিপ রেকর্ড রাখুন",
  "restaurant.doorTipPooling": "টিপ পুল ভাগ করুন এবং বছরের টিপ রেকর্ড রাখুন।",
  "tipPooling.title": "টিপ পুল",
  "tipPooling.subtitle": "আপনি যেভাবে সেট করেছেন সেভাবে টিপ পুল ভাগ করুন, এবং আপনার দলের জানানো টিপের বছরের রেকর্ড রাখুন।",
  "tipPooling.ownerOnlyNote": "পুলের সেটআপ, ভাগ ও রেকর্ড আপনার সংখ্যা। দলের সদস্য কেবল নিজের ভাগ দেখে, এবং কেবল সেই ভাগের জন্য যা আপনি প্রকাশ করেছেন।",
