  "apiErrors.tipReport": "প্রতিটি ব্যক্তির জানানো টিপ লিখুন।",
  "training.lessons.owner-tip-pooling.title": "টিপ পুল ও টিপ রেকর্ড",
  "training.lessons.owner-tip-pooling.step1": "রেস্তোরাঁ খুলুন, তারপর দল ও স্থান, তারপর টিপ পুল। কেবল মালিক পুলের সেটআপ, ভাগ ও রেকর্ড দেখেন।",
  "training.lessons.owner-tip-pooling.step2": "বেছে নিন পুল কীভাবে ভাগ হবে: ঘণ্টা অনুযায়ী, ভূমিকার শতাংশ অনুযায়ী, বা পয়েন্ট অনুযায়ী। অ্যাপ ইতিমধ্যে থাকা সময়সূচি ও ঘড়ির ঘণ্টা থেকে ভাগ করে।",
  "training.lessons.owner-tip-pooling.step3": "মেয়াদ বেছে নিন, পুলের পরিমাণ লিখুন, ভাগের পূর্বরূপ দেখুন, তারপর সংরক্ষণ করুন। সংরক্ষিত ভাগ সেই মেয়াদের বেতন পূর্বরূপে যায়।",
  "training.lessons.owner-tip-pooling.step4": "প্রস্তুত হলে সংরক্ষিত ভাগ প্রকাশ করুন — দলের সদস্য তখন কেবল নিজের ভাগ দেখে, এবং প্রকাশের আগে কিছুই দেখে না।",
  "training.lessons.owner-tip-pooling.step5": "টিপ রেকর্ড চলতে চলতে রাখুন: প্রতি ব্যক্তি, প্রতি মেয়াদে, জানানো টিপ — এবং বছরের রেকর্ড 8% হিসাবকে ফর্ম-প্রস্তুত মোটে রূপান্তর করে। অ্যাপ কেবল রেকর্ড রাখে; এটি কিছু দাখিল করে না।",
