  "training.lessons.owner-labor-warnings.title": "শ্রম সতর্কতা ঠিক করা",
  "training.lessons.owner-labor-warnings.step1": "সময়সূচি খুলুন এবং নজরদারির সংখ্যাগুলো খুঁজুন। সেখানকার প্রতিটি সংখ্যা আপনার, নিজের জায়গার জন্য ঠিক করার।",
  "training.lessons.owner-labor-warnings.step2": "সাপ্তাহিক ঘণ্টা ঠিক করুন যেখানে আপনার জন্য ওভারটাইম শুরু হয়, এবং অ্যাপ সতর্ক করার আগে কেউ কতটা কাছে আসতে পারে।",
  "training.lessons.owner-labor-warnings.step3": "ঠিক করুন শিফটে কখন বিরতি প্রত্যাশিত ও তা কত লম্বা হওয়া উচিত, এবং শিফটে আপনি সবচেয়ে আগের শুরু ও সবচেয়ে দেরি শেষ কী চান।",
  "training.lessons.owner-labor-warnings.step4": "সপ্তাহ স্বাভাবিকভাবে গড়ুন। ঘণ্টা আপনার লাইনের কাছে এলেই সতর্কতা সময়সূচিতে আসে — সেগুলো পার হওয়ার আগে।",
  "training.lessons.owner-labor-warnings.step5": "আপনার দল আসা-যাওয়া করার সঙ্গে সঙ্গে একই নজরদারি ইতিমধ্যে কাজ করা ঘণ্টার উপরও চলে, না-নেওয়া বিরতিসহ।",
  "training.lessons.owner-labor-target.title": "শ্রম লক্ষ্যের বিপরীতে সপ্তাহ গড়া",
  "training.lessons.owner-labor-target.step1": "রেস্তোরাঁ কর্নারে দল ও জায়গা তাকে শ্রম লক্ষ্য খুলুন।",
  "training.lessons.owner-labor-target.step2": "আপনার শ্রম লক্ষ্য শতাংশ হিসেবে লিখুন, এবং সপ্তাহের জন্য প্রত্যাশিত বিক্রি।",
  "training.lessons.owner-labor-target.step3": "সপ্তাহ সময়সূচিতে গড়ুন। আনুমানিক শ্রম খরচ ও % অ্যাপে ইতিমধ্যে থাকা শিফট ও হার থেকে হালনাগাদ হয়।",
  "training.lessons.owner-labor-target.step4": "আনুমানিক শ্রম % আপনার লক্ষ্য পার হলে পেজটি তা সরল কথায় বলে, পেছনের ঘণ্টা ও খরচসহ।",
  "training.lessons.owner-labor-target.step5": "সপ্তাহ কাগজে চাইলে পেজ থেকে ছাপুন — ছাপা শিটটি সেই একই নথি যা আপনি পর্দায় দেখেন।",
  "nav.cateringEvents": "ক্যাটারিং ও অনুষ্ঠান",
  "plansLib.businessIncludes.cateringEvents": "ক্যাটারিং ও ব্যক্তিগত অনুষ্ঠান — একটি অনুষ্ঠান বই, এক পৃষ্ঠার অনুষ্ঠান শিট, এবং প্রস্তুতি যা পার্টিকে আসতে দেখে",
  "restaurant.doorCateringEvents": "অনুষ্ঠান বই, এক পৃষ্ঠার অনুষ্ঠান শিট, এবং প্রতিটি অনুষ্ঠান প্রস্তুতিতে যে খাবার টানে।",
