  "catering.ownerOnlyNote": "জমা ও বকেয়া আপনার সংখ্যা। দল অনুষ্ঠান ও তার মেনু দেখে, তার টাকা কখনো নয়, এবং অনুষ্ঠান শিটের কর্মী কপিতে টাকা থাকে না।",
