  "apiErrors.cateringOwner": "শুধুমাত্র মালিক বা একজন ব্যবস্থাপক অনুষ্ঠান বই রাখতে পারেন।",
  "apiErrors.cateringInvalid": "অনুষ্ঠানের বিবরণ যাচাই করে আবার চেষ্টা করুন।",
  "training.lessons.owner-catering-events.title": "একটি ক্যাটারিং অনুষ্ঠান বুক করা",
  "training.lessons.owner-catering-events.step1": "রেস্তোরাঁ কর্নারের ফ্লোর ও অতিথি তাকে ক্যাটারিং ও অনুষ্ঠান খুলুন।",
  "training.lessons.owner-catering-events.step2": "অনুষ্ঠান যোগ করুন: তার নাম, তারিখ ও সময়, কতজন অতিথি, এবং আয়োজকের নাম ও ফোন।",
  "training.lessons.owner-catering-events.step3": "আপনার নিজের পদ থেকে মেনু বাছুন এবং প্রতিটির পরিবেশন ঠিক করুন।",
  "training.lessons.owner-catering-events.step4": "গৃহীত জমা লিখুন; অ্যাপ অনুষ্ঠানের মোট থেকে বকেয়া পাওনা রাখে। টাকা শুধু আপনি দেখেন।",
  "training.lessons.owner-catering-events.step5": "রান্নাঘর ও ফ্লোরের জন্য অনুষ্ঠান শিট ছাপুন — কর্মী কপিতে টাকা থাকে না — এবং প্রস্তুতি দেখুন, যেখানে অনুষ্ঠানের খাবার আগেই দেখা যায়।",
  "nav.reservations": "সংরক্ষণ",
  "plansLib.businessIncludes.reservations": "সংরক্ষণ ও অপেক্ষা তালিকা — সংরক্ষণের খাতা, আজ রাতের অপেক্ষা তালিকা, এবং অতিথির চাওয়া স্মরণিকাগুলি",
  "restaurant.doorReservations": "সংরক্ষণের খাতা ও আজ রাতের অপেক্ষা তালিকা",
  "staffLib.area.reservationsAccess": "সংরক্ষণ ও অপেক্ষা তালিকা",
  "staffLib.perm.reservationsHost": "সংরক্ষণ নেওয়া ও অপেক্ষা তালিকা চালানো (অভ্যর্থনা)",
  "staff.memberDialog.reservationsAccessHint": "এই টিক দিয়ে এই ব্যক্তি সংরক্ষণ নিতে ও আজ রাতের অপেক্ষা তালিকা চালাতে পারেন — অভ্যর্থনার কাজ। টিক না থাকলে খাতাটি তাঁর জন্য শুধু পড়ার। মালিক ও ব্যবস্থাপকরা সবসময় খাতা রাখতে পারেন।",
  "reservations.title": "সংরক্ষণ ও অপেক্ষা তালিকা",
  "reservations.subtitle": "আজ রাত ও সামনের রাতগুলির খাতা — কে আসছে, কতজন, আর তাদের কী লাগবে।",
  "reservations.bookNote": "এটি একটি খাতা, লাইভ খাবার ঘরের নকশা নয়: এটি মিনিটে মিনিটে টেবিলের অবস্থা জানায় না, আর এখানে অনলাইন বুকিং নেই — প্রতিটি লেখা আপনার দল ফোনে বা দরজায় নিয়েছে।",
  "reservations.hostNote": "সংরক্ষণ নেওয়া অভ্যর্থনার কাজ: মালিক, একজন ব্যবস্থাপক, অথবা যাকে মালিক অভ্যর্থনার টিক দিয়েছেন। অতিথিদের ফোন নম্বর ও ইমেল শুধু এই খাতাতেই থাকে।",
