  "apiErrors.reservationsHost": "শুধু মালিক, একজন ব্যবস্থাপক, অথবা যাকে মালিক অভ্যর্থনার টিক দিয়েছেন, তিনিই সংরক্ষণ নিতে পারেন।",
  "apiErrors.reservationsInvalid": "সংরক্ষণের বিবরণ যাচাই করে আবার চেষ্টা করুন।",
  "apiErrors.waitlistInvalid": "অপেক্ষা তালিকার বিবরণ যাচাই করে আবার চেষ্টা করুন।",
  "training.lessons.owner-reservations.title": "সংরক্ষণ নেওয়া ও অপেক্ষা তালিকা চালানো",
  "training.lessons.owner-reservations.step1": "রেস্তোরাঁ কর্নারের মেঝে ও অতিথি তাকে সংরক্ষণ খুলুন। খাতাটি প্রতিটি সংরক্ষণ রাখে; তার নিচের অপেক্ষা তালিকা আজ রাতের সংরক্ষণ-ছাড়া অতিথিদের রাখে।",
  "training.lessons.owner-reservations.step2": "তারিখ ও সময়, দলের নাম ও আকার, একটি ফোন নম্বর, এবং টেবিল বা অংশ নিজের ভাষায় লিখে একটি সংরক্ষণ যোগ করুন। রান্নাঘরের যা জানা দরকার তা লিখুন — কোনো অ্যালার্জি, উঁচু চেয়ার, কোনো বার্ষিকী।",
  "training.lessons.owner-reservations.step3": "অতিথিকে জিজ্ঞাসা করুন তিনি স্মরণিকা চান কিনা, এবং তিনি হ্যাঁ বললেই কেবল বাক্সে টিক দিন। স্মরণিকা ইমেলে যায়, আর বার্তা তৈরি হলে বার্তায়ও। আগে থেকে নেওয়া কোনো অগ্রিম — কত ও কীভাবে — শুধু রেকর্ড হিসেবে লিখুন।",
  "training.lessons.owner-reservations.step4": "সারা রাত খাতায় কাজ করুন: প্রতিটি দলকে বসেছে, আসেনি বা বাতিল বলে চিহ্নিত করুন। আজকের তালিকা খাতা থেকে দলকে পাঠান যাতে সবাই একই পৃষ্ঠা থেকে কাজ করে।",
  "training.lessons.owner-reservations.step5": "সংরক্ষণ ছাড়া অতিথিদের জন্য দলটিকে বলা অপেক্ষাসহ অপেক্ষা তালিকায় যোগ করুন। তাঁদের টেবিল তৈরি হলে টেবিল তৈরি চাপুন — সেই বার্তার জন্য নম্বর দেওয়াই অতিথির হ্যাঁ।",
  "apiErrors.smsInvalid": "একটি টেক্সটের জন্য একটি নম্বর ও একটি বার্তা দরকার।",
  "apiErrors.smsFailed": "টেক্সট পরিষেবা বার্তাটি গ্রহণ করেনি।",
