  "apiErrors.standingOrdersForbidden": "শুধুমাত্র মালিক, একজন ব্যবস্থাপক, বা ক্রয়ের অনুমতি থাকা ব্যক্তি স্থায়ী অর্ডার সেট করতে পারেন।",
  "apiErrors.standingOrdersInvalid": "স্থায়ী অর্ডারের বিবরণ যাচাই করে আবার চেষ্টা করুন।",
  "training.lessons.owner-standing-orders.title": "স্থায়ী অর্ডার এবং সরবরাহকারীর দাম তুলনা করা",
  "training.lessons.owner-standing-orders.step1": "রেস্তোরাঁ কর্নারের স্টক ও অর্ডারিং শেলফে স্থায়ী অর্ডার খুলুন। আপনার বারবারের অর্ডার এখানে থাকে, এবং সেগুলির নিচে সরবরাহকারীর দামের বই।",
  "training.lessons.owner-standing-orders.step2": "একটি স্থায়ী অর্ডার একবার সেট করুন: এটিকে একটি নাম দিন, এর সরবরাহকারী এবং এটি যে দিনের জন্য তা বেছে নিন, এবং আপনি সাধারণত যে পরিমাণ অর্ডার করেন তা দিয়ে মৌলিক লাইনগুলি যোগ করুন।",
  "training.lessons.owner-standing-orders.step3": "দিন এলে, এই সপ্তাহের খসড়া তৈরি করুন-এ ট্যাপ করুন। অ্যাপ ক্রয়ে একটি খসড়া ক্রয় অর্ডার লেখে, বই থেকে সেই সরবরাহকারীর সর্বশেষ দামে — এটি পর্যালোচনা করুন, যা দরকার বদলান, এবং নিজে পাঠান। অ্যাপ নিজে থেকে কখনো কোনো অর্ডার পাঠায় না।",
  "training.lessons.owner-standing-orders.step4": "অর্ডার করার আগে দামের বই পড়ুন: একটি উপকরণ, প্রতিটি সরবরাহকারীর সর্বশেষ দাম পাশাপাশি, সবচেয়ে সস্তাটি আগে, তারিখসহ এবং দামটি চালান থেকে এসেছে নাকি অর্ডার থেকে।",
  "training.lessons.owner-standing-orders.step5": "সরবরাহকারীর চালান এলেই তা লিখে বইটিকে সৎ রাখুন — প্রতিটি নতুন দাম বইয়ে যোগ হয় এবং পরের খসড়া তা থেকেই মূল্যায়িত হয়।",
  "nav.productionOrder": "উৎপাদন অনুযায়ী অর্ডার",
