  "training.lessons.owner-production-order.step1": "রেস্তোরাঁ কর্নারের স্টক ও অর্ডার তাকে উৎপাদন অনুযায়ী অর্ডার খুলুন। একটি উৎপাদন পরিকল্পনা — একটি ব্যাচ রান বা একটি ক্যাটারিং অনুষ্ঠান — এখানে উপকরণের অর্ডারে পরিণত হয়।",
