  "training.lessons.owner-production-order.step4": "খসড়া অর্ডার তৈরি করুন-এ ট্যাপ করুন এবং সরবরাহকারী প্রতি একটি খসড়া ক্রয় অর্ডার ক্রয়ে আসবে। নিজে পর্যালোচনা করে পাঠান — অ্যাপ কখনো নিজে থেকে অর্ডার পাঠায় না।",
  "training.lessons.owner-production-order.step5": "প্রস্তুতি পৃষ্ঠায় শিট নিজে থেকে ভরে ওঠে: প্রস্তাবিত মেক আসে আপনার পার স্তর, রিজার্ভেশন ও অনুষ্ঠানের বুকিং এবং যা ইতিমধ্যে প্রস্তুত আছে তা থেকে — পরামর্শ দেখানো হয়, এবং আপনি ব্যাচ না চালানো পর্যন্ত কিছু বদলায় না।",
